// ⚙️ IMPOSTAZIONI (si compilano una volta, solo in n8n)
// Auth Token di Twilio: console.twilio.com → Account Info → Auth Token (lo stesso della credenziale «Twilio · account»).
const AUTH_TOKEN = '';
// L'indirizzo esatto che hai incollato in Twilio (Sandbox settings → «When a message comes in»): serve per la firma.
const INDIRIZZO = 'https://kdigitalsolution.app.n8n.cloud/webhook/preventivolampo-twilio';
// Vocali: true dopo aver messo la credenziale del servizio di trascrizione nel nodo «Trascrivi il vocale».
const VOCALI_ATTIVI = false;
const TWILIO = 'https://api.twilio.com';
const TRASCRIZIONE_URL = 'https://api.openai.com/v1/audio/transcriptions';
const TRASCRIZIONE_MODELLO = 'whisper-1';

// Twilio firma ogni richiesta: HMAC-SHA1 con l'Auth Token su indirizzo + parametri in ordine alfabetico.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const p = item.json.body || {};
const out = (o) => [{ json: { TWILIO, TRASCRIZIONE_URL, TRASCRIZIONE_MODELLO, ...o } }];

function firmaValida() {
  if (!AUTH_TOKEN) return false;
  const dati = INDIRIZZO + Object.keys(p).sort().map((k) => k + p[k]).join('');
  const attesa = crypto.createHmac('sha1', AUTH_TOKEN).update(Buffer.from(dati, 'utf8')).digest('base64');
  const a = Buffer.from(attesa), b = Buffer.from(String(headers['x-twilio-signature'] || ''));
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}
if (!firmaValida()) return out({ azione: 'rifiuta', codice: 403, twiml: 'firma non valida' });
if (!String(p.From || '').startsWith('whatsapp:')) return out({ azione: 'ignora', codice: 200, twiml: '<Response></Response>' });

const base = {
  codice: 200,
  sid: p.AccountSid,
  a: p.From,
  da: p.To,
  nome: String(p.ProfileName || ''),
  testo: String(p.Body || '').trim(),
};
// L'account di prova di Twilio accetta solo risposte nel TwiML, entro 15 secondi. La bozza ne richiede ~20:
// si risponde subito «ricevuto», la si prepara dopo e la si consegna quando l'artigiano scrive «ok».
const memoria = $getWorkflowStaticData('global');
memoria.bozze = memoria.bozze || {};
const mia = memoria.bozze[base.a];
const chiedeLaBozza = /^(ok+|okay|pronta\??|bozza|link|si|sì|vai)[.!?]*$/i.test(base.testo);
const xml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rispondi = (o) => out({ ...o, twiml: '<Response><Message>' + xml(o.avviso) + '</Message></Response>' });

if (chiedeLaBozza) {
  // Una bozza non ritirata entro un'ora non si consegna più: vale l'ultimo sopralluogo.
  if (mia && mia.testo && Date.now() - (mia.il || 0) < 3600000) {
    delete memoria.bozze[base.a];
    return rispondi({ ...base, azione: 'consegna', avviso: mia.testo });
  }
  return rispondi({ ...base, azione: 'attesa', avviso: '⏳ Ci sto ancora lavorando: riscrivimi «ok» tra qualche secondo.' });
}

const media = Number(p.NumMedia || 0) > 0 ? { url: p.MediaUrl0, tipo: String(p.MediaContentType0 || '') } : null;
const vocale = media && media.tipo.startsWith('audio/') ? media : null;
const pronta = 'tra circa 20 secondi scrivimi «ok» e ti mando il link della bozza.';

if (vocale && VOCALI_ATTIVI) {
  return rispondi({ ...base, azione: 'elabora', vocale: true, mediaUrl: vocale.url, mime: vocale.tipo,
    avviso: '⏳ Ricevuto il vocale. Lo trascrivo e preparo la bozza: ' + pronta });
}
if (base.testo.length >= 15) {
  return rispondi({ ...base, azione: 'elabora', vocale: false, avviso: '⏳ Ricevuto. Preparo la bozza del preventivo: ' + pronta });
}
const aiuto = vocale
  ? 'I vocali non sono ancora attivi: scrivimi il sopralluogo come lo racconteresti a un collega e ti preparo la bozza.'
  : 'Ciao' + (base.nome ? ' ' + base.nome.split(' ')[0] : '') + '! Sono PreventivoLampo. ' + (VOCALI_ATTIVI ? 'Mandami un vocale' : 'Scrivimi') + ' dopo il sopralluogo, come lo racconteresti a un collega (lavorazioni, misure, materiali), e ti preparo la bozza del preventivo da controllare dal telefono.';
return rispondi({ ...base, azione: 'aiuto', vocale: false, avviso: aiuto });

// WhatsApp manda i vocali in OGG/Opus: il servizio di trascrizione vuole l'estensione nel nome del file.
const it = $input.first();
const mime = $('Verifica e smista').first().json.mime || 'audio/ogg';
const est = mime.includes('ogg') ? 'ogg' : mime.includes('mpeg') ? 'mp3' : mime.includes('mp4') || mime.includes('aac') ? 'm4a' : mime.includes('amr') ? 'amr' : 'ogg';
it.binary.data.fileName = 'vocale.' + est;
it.binary.data.mimeType = mime.split(';')[0];
it.binary.data.fileExtension = est;
return [it];

// La bozza è pronta: la tengo da parte per quando l'artigiano scrive «ok».
const s = $('Verifica e smista').first().json;
const r = $input.first().json;
const memoria = $getWorkflowStaticData('global');
memoria.bozze = memoria.bozze || {};
memoria.bozze[s.a] = { testo: '✅ Bozza pronta: ' + r.righe + (r.righe == 1 ? ' riga' : ' righe') + '. Controlla le voci evidenziate e approva da qui:\nhttps://preventivolampo.vercel.app' + r.revisione, il: Date.now() };
return [{ json: { salvata: true } }];

const s = $('Verifica e smista').first().json;
const memoria = $getWorkflowStaticData('global');
memoria.bozze = memoria.bozze || {};
memoria.bozze[s.a] = { testo: '⚠️ Non sono riuscito a preparare la bozza. Riprova; se succede ancora, scrivimi il sopralluogo in un unico messaggio.', il: Date.now() };
return [{ json: { salvata: false } }];
